-- Private diagnostic reports for the authenticated Edge Function.
create table if not exists public.bug_reports (id uuid primary key default gen_random_uuid(), org_id uuid not null references public.organizations(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, fingerprint text not null check (char_length(fingerprint) between 8 and 64), error_type text not null default 'Error', error_message text not null check (char_length(error_message) <= 1200), error_stack text, user_description text check (user_description is null or char_length(user_description) <= 2000), screen text, app_version text not null, environment jsonb not null default '{}'::jsonb check (jsonb_typeof(environment) = 'object'), occurrences integer not null default 1 check (occurrences > 0), status text not null default 'pending' check (status in ('pending','sent','failed')), github_issue_number bigint, github_issue_url text, github_error_code integer, first_seen timestamptz not null default now(), last_seen timestamptz not null default now(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), constraint bug_reports_org_fingerprint_key unique (org_id,fingerprint));
create index if not exists bug_reports_user_created_idx on public.bug_reports (user_id,created_at desc);
create index if not exists bug_reports_org_status_created_idx on public.bug_reports (org_id,status,created_at desc);
alter table public.bug_reports enable row level security;
revoke all on table public.bug_reports from public,anon,authenticated;
grant select,insert,update,delete on table public.bug_reports to service_role;
comment on table public.bug_reports is 'Relatórios técnicos de falhas do Super Tudo. Acesso somente pelo backend confiável.';
